mapper.select:
,NULL::timestamp AS muted_until,0::bigint AS unread_count

WHERE c.conversation_type='DIRECT'

    AND c.organization_id = #{organizationId}
    AND c.organization_id IS NULL

AND (SELECT COUNT(*) FROM marketplace_conversation_members m
     WHERE m.conversation_id = c.id AND m.left_at IS NULL) = #{memberCount}
AND (SELECT COUNT(*) FROM marketplace_conversation_members m
     WHERE m.conversation_id = c.id AND m.left_at IS NULL
       AND m.user_id IN #{userId}
    ) = #{memberCount}
ORDER BY c.created_at, c.id
LIMIT 1
